// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _number, uint64 _timestamp, uint256 _basefee, bytes32 _hash, uint64 _sequenceNumber, bytes32 _batcherHash, uint256 _l1FeeOverhead, uint256 _l1FeeScalar) public {
        // fuzzed parameters simulate any L1 block values, version() remains independent
        vm.prank(0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001);
        c.setL1BlockValues(
            uint64(bound(_number, 0, type(uint64).max)),
            _timestamp,
            _basefee,
            _hash,
            _sequenceNumber,
            _batcherHash,
            _l1FeeOverhead,
            _l1FeeScalar
        );
        assertTrue(keccak256(bytes(c.version())) == keccak256(bytes("1.0.0")));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property() public {
        string memory ver = c.version();
        bytes memory b = bytes(ver);
        bool ok = b.length > 0 && b[0] >= 0x30;
        assertTrue(ok);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function test(address caller, uint64 _number, uint64 _timestamp, uint256 _basefee, bytes32 _hash, uint64 _sequenceNumber, bytes32 _batcherHash, uint256 _l1FeeOverhead, uint256 _l1FeeScalar) external {
        require(caller != c.DEPOSITOR_ACCOUNT(), "precondition: caller is not depositor");
        bool reverted = false;
        assembly {
            let success := call(gas(), sload(c.slot), 0, 0, 0, 0, 0)
            reverted := iszero(success)
        }
        assert(false);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function test(address caller, uint64 _number) public returns (bool success) {
        vm.prank(caller);
        try c.setL1BlockValues(_number, 0, 0, bytes32(0), 0, bytes32(0), 0, 0) {
            success = true;
        } catch {
            success = false;
        }
        bool isDepositor = caller == c.DEPOSITOR_ACCOUNT();
        assert(success == isDepositor);
    }
}
